-- Housing: neighborhoods Founder's Point (map 2735) and Razorwind Shores (map 2736)
-- Spawns use their own GUID range; everything else only adds rows TDB does not have,
-- apart from the few targeted UPDATEs at the end.
SET @CGUID := 50000000;
SET @OGUID := 50000000;
SET @ATSPAWN := 50000000;

-- Creature spawns
DELETE FROM `creature` WHERE `map` IN (2735, 2736) OR `guid` BETWEEN @CGUID+0 AND @CGUID+2808;

DELETE FROM `creature_addon` WHERE `guid` BETWEEN @CGUID+0 AND @CGUID+2808;
DELETE FROM `waypoint_path` WHERE `PathId` = (@CGUID+1824)*10;
DELETE FROM `waypoint_path_node` WHERE `PathId` = (@CGUID+1824)*10;
DELETE FROM `waypoint_path` WHERE `PathId` = (@CGUID+1825)*10;
DELETE FROM `waypoint_path_node` WHERE `PathId` = (@CGUID+1825)*10;

-- GameObject spawns
DELETE FROM `gameobject` WHERE `map` IN (2735, 2736) OR `guid` BETWEEN @OGUID+0 AND @OGUID+1064;

-- AreaTrigger spawns
DELETE FROM `areatrigger` WHERE `MapId` IN (2735, 2736) OR `SpawnId` BETWEEN @ATSPAWN+0 AND @ATSPAWN+17;

